# Génère content-src/i2026/i2026.json : exercices INSPIRÉS des évaluations interdiocésaines P4 de juin 2026
# (textes et questions originaux, mêmes compétences). Usage : python3 tools/build-i2026.py
import json, os, hashlib, unicodedata
OUT = os.path.join(os.path.dirname(__file__), '..', 'content-src', 'i2026', 'i2026.json')
Q, P, O = [], [], []
cnt = {}
def nid(doc):
    cnt[doc] = cnt.get(doc, 0) + 1
    return f'i26-{doc}-{cnt[doc]:02d}'
def norm(s):
    return ''.join(c for c in unicodedata.normalize('NFD', str(s).lower()) if unicodedata.category(c) != 'Mn').strip()
def qcm(doc, subj, dom, lvl, prompt, good, bad, why, hint='', passage=None):
    i = nid(doc); ch = [good] + list(bad)
    pos = int(hashlib.md5(i.encode()).hexdigest(), 16) % len(ch)
    ch.insert(pos, ch.pop(0))
    Q.append(dict(id=i, subject=subj, domain=dom, level=lvl, type='qcm', prompt=prompt, choices=ch, answer=pos,
                  explanation=why, hint=hint, passage=passage, source='inspire_2026', exam2026=doc))
def sai(doc, subj, dom, lvl, prompt, acc, why, hint='', passage=None):
    i = nid(doc)
    Q.append(dict(id=i, subject=subj, domain=dom, level=lvl, type='saisie', prompt=prompt, accepted=sorted({norm(a) for a in acc}),
                  explanation=why, hint=hint, passage=passage, source='inspire_2026', exam2026=doc))
def pas(doc, key, subj, dom, lvl, title, text):
    i = f'i26-p-{doc}-{key}'
    P.append(dict(id=i, title=title, text=text, subject=subj, domain=dom, level=lvl, source='inspire_2026', exam2026=doc)); return i
def task(doc, subj, dom, lvl, prompt, rubric):
    O.append(dict(id=nid(doc).replace('i26-', 'i26-o-'), subject=subj, domain=dom, level=lvl, prompt=prompt, rubric=rubric, passage=None, source='inspire_2026', exam2026=doc))
F, M, E = 'francais', 'maths', 'eveil'

